Json::Json():value_(nullptr){} Json::Json(std::nullptr_t):value_(nullptr){} Json::Json(bool v):value_(v){}
Json::Json(std::int64_t v):value_(v){} Json::Json(const char* v):value_(std::string(v)){}
Json::Json(std::string v):value_(std::move(v)){} Json::Json(Array v):value_(std::move(v)){} Json::Json(Object v):value_(std::move(v)){}
bool Json::is_null()const{return std::holds_alternative<std::nullptr_t>(value_);} bool Json::is_bool()const{return std::holds_alternative<bool>(value_);}
bool Json::is_int()const{return std::holds_alternative<std::int64_t>(value_);} bool Json::is_string()const{return std::holds_alternative<std::string>(value_);}
bool Json::is_array()const{return std::holds_alternative<Array>(value_);} bool Json::is_object()const{return std::holds_alternative<Object>(value_);}
bool Json::as_bool()const{if(!is_bool())throw JsonError("expected boolean");return std::get<bool>(value_);} std::int64_t Json::as_int()const{if(!is_int())throw JsonError("expected integer");return std::get<std::int64_t>(value_);}
const std::string& Json::as_string()const{if(!is_string())throw JsonError("expected string");return std::get<std::string>(value_);} const Json::Array& Json::as_array()const{if(!is_array())throw JsonError("expected array");return std::get<Array>(value_);} Json::Array& Json::as_array(){if(!is_array())throw JsonError("expected array");return std::get<Array>(value_);}
const Json::Object& Json::as_object()const{if(!is_object())throw JsonError("expected object");return std::get<Object>(value_);} Json::Object& Json::as_object(){if(!is_object())throw JsonError("expected object");return std::get<Object>(value_);}
const Json& Json::at(const std::string& k)const{const auto& o=as_object();auto i=o.find(k);if(i==o.end())throw JsonError("missing field: "+k);return i->second;} bool Json::contains(const std::string& k)const{return is_object()&&as_object().count(k)!=0;}

static std::string esc(const std::string& s){std::ostringstream o;o<<'"';for(unsigned char c:s){switch(c){case '"':o<<"\\\"";break;case '\\':o<<"\\\\";break;case '\b':o<<"\\b";break;case '\f':o<<"\\f";break;case '\n':o<<"\\n";break;case '\r':o<<"\\r";break;case '\t':o<<"\\t";break;default:if(c<0x20)o<<"\\u"<<std::hex<<std::setw(4)<<std::setfill('0')<<static_cast<unsigned>(c)<<std::dec;else o<<static_cast<char>(c);}}o<<'"';return o.str();}
std::string Json::dump(bool pretty,unsigned indent)const{std::ostringstream o;const auto pad=[&](unsigned n){return std::string(n,' ');};if(is_null())o<<"null";else if(is_bool())o<<(as_bool()?"true":"false");else if(is_int())o<<as_int();else if(is_string())o<<esc(as_string());else if(is_array()){o<<'[';const auto&a=as_array();for(std::size_t i=0;i<a.size();++i){if(i)o<<',';if(pretty)o<<'\n'<<pad(indent+2);o<<a[i].dump(pretty,indent+2);}if(pretty&&!a.empty())o<<'\n'<<pad(indent);o<<']';}else{o<<'{';const auto&obj=as_object();std::size_t i=0;for(const auto&kv:obj){if(i++)o<<',';if(pretty)o<<'\n'<<pad(indent+2);o<<esc(kv.first)<<':'<<(pretty?" ":"")<<kv.second.dump(pretty,indent+2);}if(pretty&&!obj.empty())o<<'\n'<<pad(indent);o<<'}';}return o.str();}

class Parser{const std::string&s;std::size_t p=0;unsigned maxd;void ws(){while(p<s.size()&&std::isspace(static_cast<unsigned char>(s[p])))++p;}[[noreturn]]void fail(const std::string&m)const{throw JsonError(m+" at byte "+std::to_string(p));}char get(){if(p>=s.size())fail("unexpected end");return s[p++];}
 static bool utf8(const std::string&v){for(std::size_t i=0;i<v.size();){unsigned char c=v[i++];if(c<0x80)continue;unsigned n=c>=0xC2&&c<=0xDF?1:c>=0xE0&&c<=0xEF?2:c>=0xF0&&c<=0xF4?3:99;if(n==99||i+n>v.size())return false;unsigned char first=static_cast<unsigned char>(v[i]);if((c==0xE0&&first<0xA0)||(c==0xED&&first>=0xA0)||(c==0xF0&&first<0x90)||(c==0xF4&&first>=0x90))return false;for(unsigned k=0;k<n;++k)if((static_cast<unsigned char>(v[i++])&0xC0)!=0x80)return false;}return true;}
 std::string str(){if(get()!='"')fail("expected string");std::string out;while(p<s.size()){unsigned char c=static_cast<unsigned char>(get());if(c=='"'){if(!utf8(out))fail("invalid UTF-8");return out;}if(c<0x20)fail("control character in string");if(c=='\\'){char e=get();switch(e){case '"':case '\\':case '/':out+=e;break;case 'b':out+='\b';break;case 'f':out+='\f';break;case 'n':out+='\n';break;case 'r':out+='\r';break;case 't':out+='\t';break;case 'u':{unsigned v=0;for(int i=0;i<4;++i){char h=get();v*=16;if(h>='0'&&h<='9')v+=h-'0';else if(h>='a'&&h<='f')v+=h-'a'+10;else if(h>='A'&&h<='F')v+=h-'A'+10;else fail("bad unicode escape");}if(v>=0xD800&&v<=0xDFFF)fail("surrogate unsupported");if(v<0x80)out+=static_cast<char>(v);else if(v<0x800){out+=static_cast<char>(0xC0|(v>>6));out+=static_cast<char>(0x80|(v&63));}else{out+=static_cast<char>(0xE0|(v>>12));out+=static_cast<char>(0x80|((v>>6)&63));out+=static_cast<char>(0x80|(v&63));}break;}default:fail("bad escape");}}else out+=static_cast<char>(c);if(out.size()>1024U*1024U)fail("string too large");}fail("unterminated string");}
 Json val(unsigned d){if(d>maxd)fail("maximum nesting exceeded");ws();if(p>=s.size())fail("unexpected end");if(s[p]=='"')return Json(str());if(s[p]=='{'){++p;Json::Object o;ws();if(p<s.size()&&s[p]=='}'){++p;return Json(std::move(o));}for(;;){ws();std::string k=str();if(k.size()>4096)fail("key too large");ws();if(get()!=':')fail("expected colon");if(!o.emplace(k,val(d+1)).second)fail("duplicate key");if(o.size()>200000)fail("object too large");ws();char c=get();if(c=='}')break;if(c!=',')fail("expected comma");}return Json(std::move(o));}if(s[p]=='['){++p;Json::Array a;ws();if(p<s.size()&&s[p]==']'){++p;return Json(std::move(a));}for(;;){a.push_back(val(d+1));if(a.size()>200000)fail("array too large");ws();char c=get();if(c==']')break;if(c!=',')fail("expected comma");}return Json(std::move(a));}if(s.compare(p,4,"true")==0){p+=4;return Json(true);}if(s.compare(p,5,"false")==0){p+=5;return Json(false);}if(s.compare(p,4,"null")==0){p+=4;return Json();}bool neg=false;if(s[p]=='-'){neg=true;++p;}if(p>=s.size()||!std::isdigit(static_cast<unsigned char>(s[p])))fail("invalid number");std::int64_t n=0;while(p<s.size()&&std::isdigit(static_cast<unsigned char>(s[p]))){int dgt=s[p++]-'0';if(n>(INT64_MAX-dgt)/10)fail("integer overflow");n=n*10+dgt;}if(p<s.size()&&(s[p]=='.'||s[p]=='e'||s[p]=='E'))fail("floating point unsupported");return Json(neg?-n:n);}
public:Parser(const std::string&i,unsigned d):s(i),maxd(d){}Json parse(){Json j=val(0);ws();if(p!=s.size())fail("trailing data");return j;}};
Json Json::parse(const std::string& input,std::size_t max_bytes,unsigned max_depth){if(input.size()>max_bytes)throw JsonError("JSON exceeds size limit");return Parser(input,max_depth).parse();}
